// ui/routes/runs/artifacts.mjs — feature "runs" (docs/runs.md). Generated by tools/split-by-feature.mjs v1;
// the body of register() was moved verbatim from ui/server.mjs. Edit it here from now on.
import { findPipelineRowById, listArtifacts, listRunArtifacts, lookupPipelineRow, readRunArtifactText, resolveIndexedArtifactForRow, runDirForRow, runEngineOfRow } from '../../../src/core/artifacts.mjs';
import { ASK_LIMITS } from '../../../src/core/ask/limits.mjs';
import { failedBecauseSignedOut } from '../../../src/core/claude-auth.mjs';
import { listModels, modelCostConfig } from '../../../src/core/config.mjs';
import { requireFlag } from '../../../src/core/flags.mjs';
import { helperEngineFor } from '../../../src/core/model-env.mjs';
import { modelFacts } from '../../../src/core/model-tiers.mjs';
import { generateOverview } from '../../../src/core/overview-agent.mjs';
import { CLAUDE_SIGNED_OUT_CODE, CLAUDE_SIGNED_OUT_MESSAGE } from '../../../src/core/preflight.mjs';
import { DIFF_PATCH_FILE } from '../../../src/core/results.mjs';
import { projectKey } from '../../../src/core/store.mjs';
import { TELEMETRY_FILE } from '../../../src/core/telemetry/recorder.mjs';
import { summarizeTelemetry } from '../../../src/core/telemetry/summary.mjs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import { askFilesRunDir, badRequest, liveDiffOf, liveRunEntry, resolveProjectDir, resolveRunScope, sendArtifactRaw, serveAskFile } from '../../server.mjs';

export function register(app) {

// GET /api/runs/:id/artifact?rel= -> the same payload, resolved by the pipeline
// id ALONE (findPipelineRowById): the Running page knows the run's pipelineId
// but no store key until History has been visited. Placed beside /api/runs/:id
// (`:id` matches one path segment, so the two never shadow each other).
app.get('/api/runs/:id/artifact', async (req, res) => {
  try {
    const row = findPipelineRowById(req.params.id);
    if (!row) return res.status(404).json({ error: 'pipeline not found' });
    const hit = await resolveIndexedArtifactForRow(row, req.query.rel);
    if (!hit) return res.status(404).json({ error: 'artifact not found' });
    res.json(hit);
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// GET /api/runs/:id/telemetry -> Run telemetry (Labs): telemetry.ndjson summarised per step
// (src/core/telemetry/summary.mjs), by the pipeline id alone like /artifact above. 404 while the
// flag is off, and when the run recorded none (it ran with the flag off).
app.get('/api/runs/:id/telemetry', requireFlag('runTelemetry'), async (req, res) => {
  try {
    const row = findPipelineRowById(req.params.id);
    if (!row) return res.status(404).json({ error: 'pipeline not found' });
    let text;
    try { text = await fsp.readFile(path.join(await runDirForRow(row), TELEMETRY_FILE), 'utf8'); } catch { return res.status(404).json({ error: 'no telemetry' }); }
    let facts = [];
    try { facts = modelFacts(await listModels(''), { costOf: modelCostConfig }); } catch { facts = []; }
    const windowOf = (model) => {
      if (!model) return null;
      const f = facts.find((x) => x.id === model) || modelFacts([{ id: model }])[0];
      return f ? { tokens: f.context, from: f.contextFrom } : null;
    };
    res.json(summarizeTelemetry(text, { windowOf }));
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.get('/api/runs/:id/artifacts', async (req, res) => {
  try {
    const row = findPipelineRowById(req.params.id);
    if (!row) return res.status(404).json({ error: 'pipeline not found' });
    // Cap the row set (each row costs a synchronous statSync for its byte size, on
    // the event loop) at the same ceiling the ask tool uses — and fetch one extra
    // row to SAY so, the way list_run_artifacts does. A three-deck presentation
    // run indexes past 200, and a partial list the client cannot tell is partial
    // renders as the whole run.
    const limit = ASK_LIMITS.artifactsListMaxLimit;
    // ...and hand back the cursor, so the cap is a page boundary rather than a
    // wall. Rows are oldest-first, so what a truncated list omits is the NEWEST —
    // the deliverables — and `truncated` alone left the Artifacts tab saying "this
    // run indexed more" with nothing behind it. Junk clamps to 0 rather than
    // reaching SQL: Number('abc') is NaN and a negative offset is meaningless.
    const asked = Number(req.query.offset);
    // Clamped to MAX_SAFE_INTEGER, the way the ask tool's clampInt does: a finite
    // but absurd `?offset=1e20` is still an integer to Number.isInteger, and
    // node:sqlite refuses to bind it — which came back as a 500 rather than the
    // empty page an offset past the end should be.
    const offset = Number.isFinite(asked) && asked > 0
      ? Math.min(Math.floor(asked), Number.MAX_SAFE_INTEGER) : 0;
    const rows = await listRunArtifacts(row.id, { limit: limit + 1, offset, browsableOnly: true });
    const truncated = rows.length > limit;
    res.json({
      runId: row.id,
      artifacts: rows.slice(0, limit),
      truncated,
      ...(truncated ? { nextOffset: offset + limit } : {}),
    });
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.get('/api/runs/:id/ask-files/:askId/:index', async (req, res) => {
  try {
    await serveAskFile(res, await askFilesRunDir(req.params.id), req.params.askId, req.params.index);
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.get('/api/runs/:id/artifact-raw/*splat', async (req, res) => {
  try {
    const row = findPipelineRowById(req.params.id);
    if (!row) return res.status(404).json({ error: 'pipeline not found' });
    await sendArtifactRaw(res, row, req.params.splat.join('/'), { download: req.query.download === '1' });
  } catch (err) { res.status(500).json({ error: err && err.message ? err.message : String(err) }); }
});
app.get('/api/runs/:id/live-diff', async (req, res) => {
  const entry = liveRunEntry(req.params.id);
  if (!entry || !entry.orch || typeof entry.orch.liveDiff !== 'function') {
    return res.status(404).json({ error: 'run not live' });
  }
  try {
    const out = await liveDiffOf(entry);
    if (!out) return res.status(404).json({ error: 'no worktree yet' });
    res.json(out);
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// Download the durable done-path diff as an alternate recovery route for a
// retained worktree. The filename is fixed; callers cannot supply a path.
app.get('/api/runs/:id/recovery-patch', async (req, res) => {
  const id = req.params.id;
  const scope = resolveRunScope(req, res);
  if (!scope) return;
  const key = scope.key; // the body's readRunArtifactText(key, …) calls stay unchanged
  try {
    // Prefer a retained-work snapshot (any member's, incl. workspace-suffixed
    // names) over the done-path diff. Resolved through the artifacts INDEX, which
    // only gains a row on a SUCCESSFUL snapshot — a truncated or missing file can
    // never shadow the diff-patch fallback.
    const arts = await listArtifacts(id).catch(() => []);
    const retainedRel = arts.find((a) => a && a.kind === 'retained-work-patch')?.relPath || null;
    let filename = null;
    let patch = retainedRel == null ? null : await readRunArtifactText(key, id, retainedRel);
    if (patch != null && patch.length) {
      filename = `retained-work-${String(id).replace(/[^a-zA-Z0-9._-]/g, '-')}.patch`;
    } else {
      patch = await readRunArtifactText(key, id, DIFF_PATCH_FILE);
      filename = `diff-patch-${String(id).replace(/[^a-zA-Z0-9._-]/g, '-')}.patch`;
    }
    if (patch == null) return res.status(404).json({ error: 'recovery patch not found' });
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    res.type('text/x-diff').send(patch);
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// ---------------------------------------------------------------------------
// POST /api/runs/:id/overview  -> Layer-2 on-demand overview agent.
// Accepts ?key=<storeKey> (preferred; history detail uses it) or ?projectDir=...
// ?force=1 bypasses the cached overview.json. 200 { overview } | 404 | 500, or
// 409 code 'claude-signed-out' when a Claude run's CLI is signed out (a cached overview
// needs no Claude, so this maps the failure instead of probing up front).
// ---------------------------------------------------------------------------
app.post('/api/runs/:id/overview', async (req, res) => {
  const id = req.params.id;
  let key = typeof req.query.key === 'string' ? req.query.key : null;
  if (!key) {
    const projectDir = resolveProjectDir(req.query.projectDir);
    if (!projectDir) return badRequest(res, 'key or projectDir is required');
    key = projectKey(projectDir);
  }
  const force = req.query.force === '1' || req.query.force === 'true';
  // The run's own engine (§4.3): only a failure on Claude can be the Claude sign-in (a Cursor run's overview runs on Claude).
  const runEngine = runEngineOfRow(lookupPipelineRow(key, id));
  try {
    const overview = await generateOverview(key, id, { force });
    res.json({ overview });
  } catch (err) {
    const msg = err && err.message ? err.message : String(err);
    if (msg !== 'pipeline not found' && helperEngineFor(runEngine) === 'claude' && await failedBecauseSignedOut({ message: msg })) {
      return res.status(409).json({ code: CLAUDE_SIGNED_OUT_CODE, error: CLAUDE_SIGNED_OUT_MESSAGE });
    }
    const code = msg === 'pipeline not found' ? 404 : 500;
    res.status(code).json({ error: msg });
  }
});
}
